def Sys.toWorld (s : Sys) : Singular.World :=
  { registry := { config := s.config, trie := s.trie,
                  held := s.carriers.map (·.original) },
    pending := s.registrations,
    terminations := s.terminations.map (·.booking), treasury := s.treasury }

def foldEffect (world : World) (tx : EconomicTransaction) (result : Result) : World :=
  { registry := foldRegistryEffect world tx result,
    pending := world.pending.filter fun b =>
      !inputsContainReference tx.transaction.inputs b.request.reference,
    terminations := foldRemainingTerminations world tx,
    treasury := world.treasury + tx.transaction.donation }

def foldLegacyRequest (c : Config) (member : FoldMember) : Request :=
  let (edge, key, owner, destination, datum, submittedAt) := match member with
    | .registration b => (.insertActive, b.request.key, b.request.refundAddress,
        b.request.destination, b.request.datum, b.request.submittedAt)
    | .termination b => (.updateTerminal, b.request.key, 0, b.request.destination, none, 0)
  let approval : Approval :=
    { policy := c.applicationPolicy, edge, key, owner, destination,
      assetName := approvalAssetName edge key owner destination }
  { edge, key, owner, output := destination, datum, submittedAt,
    registryId := c.registryId, claimed := delta edge, approval := some approval }

def foldRegistryEffect (world : World) (tx : EconomicTransaction) (result : Result) : RegistryState :=
  { result.state with held := result.state.held.filter fun holding =>
      !(holding.kind == .active && (foldRemainingTerminations world tx).any
        (fun b => b.request.key == holding.key)) }

def foldObligations (members : List FoldMember) : FoldObligations :=
  { donation := (members.map FoldMember.donation).sum,
    tips := (members.map FoldMember.tip).sum,
    carriers := (members.map FoldMember.carrier).sum }

def foldOrdinary (output : EconomicOutput) : Bool :=
  output.output.stateTokens == 0 && output.contents.trieReadyTags.isEmpty &&
    output.contents.applicationTags.isEmpty && output.singularTags.isEmpty

def observesWorld (world : World) (u : EconomicUtxo) : Bool :=
  world.pending.all (fun b => observesRegistration u b.request) &&
    world.terminations.all (fun b => observesTermination u b.request)

def refundAmount (request : RegistrationRequest) (retraction : Bool) : Nat :=
  if retraction then request.contents.lovelace
  else request.contents.lovelace - request.declaredTip

def refundPaid (tx : EconomicTransaction) (address : Nat) : Nat :=
  ((tx.outputs.filter fun o => o.output.address == some address).map
    fun o => o.output.lovelace).sum

def refundRefusal (tx : EconomicTransaction) (obligations : List (Nat × Nat))
    (reason : String) : Option String :=
  if obligations.all (fun obligation => decide (obligation.2 ≤ refundPaid tx obligation.1))
  then none else some reason

def rejectionEffect (world : World) (r : Rejection) : World :=
  { world with pending := world.pending.filter fun b =>
      !(r.members.any fun m => m.1 == b.request.reference) }

def retractionEffect (world : World) (tx : EconomicTransaction) : World :=
  { world with pending := world.pending.filter fun b =>
      !inputsContainReference tx.transaction.inputs b.request.reference }

def retractionFundingLovelace (u : EconomicUtxo) (tx : EconomicTransaction)
    (request : RegistrationRequest) : Nat :=
  foldOrdinaryLovelace (retractionFunding u tx request)

def terminationContentsShape (c : Config) (r : TerminationRequest) : Bool :=
  decide (c.minimumTip ≤ r.declaredTip ∧ r.contents.otherAssets = [] ∧
    r.refundAddress = none ∧ r.submittedAt = none ∧ r.contents.applicationTags = [])

def bookTermination (world : World) (booking : TerminationBooking) : Except String World :=
  match terminationBookingRefusal world.registry booking with
  | some reason => .error reason
  | none =>
    if world.pending.any (fun p => decide (p.request.reference = booking.request.reference)) ||
        world.terminations.any (fun p => decide (p.request.reference = booking.request.reference)) then
      .error "request-already-pending"
    else .ok {
      world with
      registry := { world.registry with
        held := world.registry.held.filter (fun h => !(h.key == booking.request.key && h.kind == .active)) }
      terminations := booking :: world.terminations }

def assetPlus (a b : List (Asset × Int)) : List (Asset × Int) :=
  ((a.map Prod.fst ++ b.map Prod.fst).eraseDups).map fun x =>
    (x, assetKind a x + assetKind b x)

def applyEdge (s : RegistryState) (a : Action) : Result :=
  let state : RegistryState :=
    match a.edge with
    | .insertActive =>
      let trie := trieSet s.trie a.key (.known .active)
      { s with trie := trie
             , config := { s.config with root := rootOf trie }
             , held := { key := a.key, kind := .active, output := a.output
                        , datum := a.datum } :: s.held }
    | .updateTerminal =>
      let trie := trieSet s.trie a.key (.known .terminal)
      { s with trie := trie
             , config := { s.config with root := rootOf trie }
             , held := s.held.filter fun h => !(h.key == a.key && h.kind == .active) }
    | _ => s
  { state, mint := assetDelta a, paid := [] }

def rootOf (t : Trie) : ByteArray :=
  let sorted := (t.toArray.qsort (fun a b => a.1 < b.1)).toList
  let bytes : List UInt8 :=
    sorted.flatMap fun p =>
      u64bytes (fnv1a [p.1.toUInt8]) ++ [p.1.toUInt8, leafByte p.2]
  ByteArray.mk (u64bytes (fnv1a bytes)).toArray
